/// <summary>
/// Service class for sales picking list generation service
/// </summary>
class METSalesPickingListGenerationService extends SysOperationServiceBase
{
    METSalesPickingListGenerationContract   dataContract;
    //Batch                                   batchTask;
    //Batch                                   batchTaskCurrent;
    BatchHeader                             batchHeader;

}

Method.Source:
    /// <summary>
    /// processing logic
    /// </summary>
    /// <param name = "_dataContract">The data contract</param>
    public void process(METSalesPickingListGenerationContract _dataContract)
    {
        dataContract = _dataContract;

        this.initialise();
        this.processTasks();
    }

/// <summary>Initialise global variables</summary>
public void initialise()
{
    batchHeader         = BatchHeader::construct();         
}

    /// <summary>Create sub tasks that do the actual calculations</summary>
    public void processTasks()
    {        
        int i;
        METSalesPickingListGenerationTaskController         salesPickingListGenerationTaskController;
        METSalesPickingListGenerationTaskContract           salesPickingListGenerationTaskContract;


        for(i = 1; i <= conLen(dataContract.parmSalesOrderList()); i++)
        {
            salesPickingListGenerationTaskController = METSalesPickingListGenerationTaskController::construct();                
            salesPickingListGenerationTaskContract = this.buildDataContract(salesPickingListGenerationTaskController, conPeek(dataContract.parmSalesOrderList(), i));            
            batchHeader.addTask(salesPickingListGenerationTaskController);
        }

        batchHeader.parmCaption(strFmt("@MET:ExtractServiceBy", "@MET:MetPickingListGeneration", curUserId()));
        batchHeader.save();             
    }

/// <summary>
/// contract METSalesPickingListGenerationTaskContract
/// </summary>
/// <param name = "_taskController">METSalesPickingListGenerationTaskController</param>
/// <param name = "_salesOrderList">sales order list</param>
/// <returns>METSalesPickingListGenerationTaskContract</returns>
public METSalesPickingListGenerationTaskContract buildDataContract(METSalesPickingListGenerationTaskController _taskController, container _salesOrderList)
{
    METSalesPickingListGenerationTaskContract   salesPickingListGenerationTaskContract;
    
    salesPickingListGenerationTaskContract = _taskController.getDataContractObject();
    salesPickingListGenerationTaskContract.parmSalesId(conPeek(_salesOrderList, 1));
    salesPickingListGenerationTaskContract.parmOSCCodeList(conDel(_salesOrderList, 1, 1));
    
    return salesPickingListGenerationTaskContract;
}
